import urllib.request,urllib.parse,json
from html.parser import HTMLParser
class P(HTMLParser):
 def __init__(self): super().__init__(); self.tables=[]; self.in_table=0; self.rows=[]; self.row=None; self.cell=None
 def handle_starttag(self,t,a):
  if t=='table': self.in_table+=1; self.rows=[]
  elif self.in_table and t=='tr': self.row=[]
  elif self.in_table and t in ('td','th'): self.cell=[]
 def handle_data(self,d):
  if self.in_table and self.cell is not None: self.cell.append(d)
 def handle_endtag(self,t):
  if self.in_table and t in ('td','th') and self.cell is not None:
   self.row.append(' '.join(' '.join(self.cell).split())); self.cell=None
  elif self.in_table and t=='tr' and self.row is not None:
   if self.row: self.rows.append(self.row)
   self.row=None
  elif t=='table' and self.in_table:
   self.tables.append(self.rows); self.in_table-=1
